export function installTestHook(){
  if(APP_ENV !== "test") return;   // set by window.__HANGTAG_TEST__ (shared/config/app-config.js)
  const byName = new Map();
  MODULE_NAMESPACES.forEach(ns => Object.keys(ns).forEach(k => byName.set(k, ns)));
  const state = new Set(STATE_KEYS);
  const scope = new Proxy(Object.create(null), {
    has: (_, k) => typeof k === "string" && (state.has(k) || byName.has(k)),
    get: (_, k) => k === Symbol.unscopables ? undefined : state.has(k) ? store[k] : byName.get(k)[k],
    set: (_, k, v) => { if(state.has(k)){ store[k] = v; return true; } throw new TypeError(String(k) + " is a module export and can't be replaced from a test"); }
  });
  // A non-strict Function so the evaluated code can use `with` scope lookups.
  const run = new Function("scope", "src", "with (scope) { return eval(src); }");
  window.__ev = src => run(scope, src);
}
